<template>
  <div class="app-container">
    <div class="page-hero"><div class="hero-inner"><div class="hero-text"><h1 class="hero-title">生存率比较 (Log-Rank 检验)</h1><p class="hero-desc">比较两组生存曲线是否有统计学差异，通过 Log-Rank χ² 统计量判断两组总体生存分布是否相同，同时绘制两组 Kaplan-Meier 生存曲线叠加对比图</p></div><el-tag class="hero-tag" effect="dark" round>SURVIVAL · LOG-RANK</el-tag></div></div>
    <el-row :gutter="20" class="mb-4 input-row">
      <el-col :lg="16" :xs="24"><el-card shadow="never" class="input-card"><el-form label-position="top"><el-row :gutter="16"><el-col :span="12"><el-form-item label="组1数据（每行：时间,结局）"><el-input v-model="form.data1" type="textarea" :rows="4" placeholder="1,1&#10;3,0" /></el-form-item></el-col><el-col :span="12"><el-form-item label="组2数据"><el-input v-model="form.data2" type="textarea" :rows="4" /></el-form-item></el-col></el-row></el-form><div class="action-bar"><el-button type="primary" class="calc-btn" @click="calculate"><el-icon class="mr-1"><DataAnalysis /></el-icon>开始计算</el-button><el-button class="reset-btn" @click="loadDemo">加载示例</el-button><el-button class="reset-btn" @click="clearAll">清除</el-button></div></el-card></el-col>
      <el-col :lg="8" :xs="24"><div class="param-sidebar"><div class="param-sidebar-header"><el-icon class="sidebar-icon"><InfoFilled /></el-icon>检验原理</div><div class="principle-content"><div class="principle-block"><div class="principle-label">假设</div><p>H₀: 两组生存分布相同</p></div><div class="principle-block"><div class="principle-label">统计量</div><div class="formula-box">χ² = (O₁ - E₁)² / E₁</div></div></div><div class="ref-section"><div class="ref-title">参考文献</div><p class="ref-item">[1] 方积乾.《卫生统计学》第7版, 2012.</p></div></div></el-col>
    </el-row>
    <transition name="result-fade"><div v-if="res" class="result-section">
      <div class="metrics-grid mb-5"><div v-for="m in metrics" :key="m.label" class="metric-card" :class="m.type"><div class="metric-indicator" /><div class="metric-label">{{ m.label }}</div><div class="metric-value">{{ m.value }}</div></div></div>
      <el-card shadow="never" class="detail-card mb-4"><template #header><div class="card-header-inner"><el-icon class="header-icon"><TrendCharts /></el-icon><span class="font-bold">生存曲线比较</span></div></template><ECharts :options="chartOpts" height="340px" /></el-card>
    </div></transition>
  </div>
</template>
<script setup lang="ts">
import { InfoFilled, DataAnalysis, TrendCharts } from "@element-plus/icons-vue"; import * as S from "../utils/stats";
defineOptions({ name: "SurvivalCompare" }); const form = reactive({ data1: "", data2: "" }); const res = ref(false); const metrics = ref<any[]>([]); const chartOpts = ref({});
function loadDemo() { form.data1 = "1,1\n3,1\n5,0\n7,1\n9,1\n12,0\n15,1\n20,0"; form.data2 = "2,1\n4,1\n6,1\n8,0\n10,1\n14,1\n18,1\n25,0"; calculate(); }
function clearAll() { form.data1 = ""; form.data2 = ""; res.value = false; }
function parseGroup(text: string) { return text.trim().split("\n").map(l => { const p = S.parseNumbers(l); return { time: p[0], event: p[1] || 0 }; }).filter(r => r.time != null).sort((a, b) => a.time - b.time); }
function kmCurve(data: { time: number; event: number }[]) { const n = data.length; let atRisk = n, surv = 1; const curve: [number, number][] = [[0, 1]]; const times = [...new Set(data.map(r => r.time))].sort((a, b) => a - b); times.forEach(t => { const ev = data.filter(r => r.time === t && r.event === 1).length; const ce = data.filter(r => r.time === t && r.event === 0).length; if (ev > 0) surv *= (1 - ev / atRisk); curve.push([t, +surv.toFixed(4)]); atRisk -= ev + ce; }); return curve; }
function calculate() {
  const g1 = parseGroup(form.data1), g2 = parseGroup(form.data2); if (g1.length < 2 || g2.length < 2) return;
  const all = [...g1.map(r => ({ ...r, g: 1 })), ...g2.map(r => ({ ...r, g: 2 }))].sort((a, b) => a.time - b.time);
  const times = [...new Set(all.map(r => r.time))].sort((a, b) => a - b);
  let n1 = g1.length, n2 = g2.length, O1 = 0, E1 = 0;
  times.forEach(t => { const d1 = all.filter(r => r.time === t && r.g === 1 && r.event === 1).length; const d2 = all.filter(r => r.time === t && r.g === 2 && r.event === 1).length; const d = d1 + d2, n = n1 + n2; if (n > 0 && d > 0) E1 += n1 * d / n; O1 += d1; const c1 = all.filter(r => r.time === t && r.g === 1).length; const c2 = all.filter(r => r.time === t && r.g === 2).length; n1 -= c1; n2 -= c2; });
  const chi2 = E1 > 0 ? (O1 - E1) ** 2 / E1 : 0; const pVal = S.chiSquarePValue(chi2, 1); const sig = pVal < 0.05; res.value = true;
  metrics.value = [{ label: "组1 n", value: g1.length, type: "accent" }, { label: "组2 n", value: g2.length, type: "accent" }, { label: "χ² (Log-Rank)", value: S.fmt(chi2), type: "warning" }, { label: "P", value: S.fmtP(pVal), type: sig ? "warning" : "neutral" }, { label: "结论", value: sig ? "生存率有差异" : "无显著差异", type: sig ? "warning" : "neutral" }];
  chartOpts.value = { tooltip: { trigger: "axis" }, legend: { data: ["组1", "组2"], bottom: 0 }, grid: { left: "8%", right: "4%", bottom: "14%", top: "6%" }, xAxis: { type: "value", name: "时间" }, yAxis: { type: "value", name: "S(t)", max: 1 }, series: [{ name: "组1", type: "line", data: kmCurve(g1), step: "end", lineStyle: { width: 2.5, color: "#4558d0" }, showSymbol: false }, { name: "组2", type: "line", data: kmCurve(g2), step: "end", lineStyle: { width: 2.5, color: "#e6a23c" }, showSymbol: false }] };
}
</script>
